import { readFileSync } from 'node:fs';
import type { HeaderSceneArt, SceneLayer } from '@splitbook/shared/header-scene-art';
import { ecoScene, ecoCss } from './eco-city.ts';
import { alpScene, alpCss } from './mountain-village.ts';
import { beachScene, beachCss } from './beach.ts';
import { sakuraScene, sakuraCss } from './sakura.ts';
import { vectorTree } from './vectors.ts';

export const OUTPUT = 'packages/shared/src/header-scenes';
const NOTICE =
  '// Generated by tools/header-scenes. Run pnpm --filter @splitbook/header-scenes build.\n// Do not edit by hand.\n';
export const sharedCss = () => readFileSync(new URL('./scene.css', import.meta.url), 'utf8');
export function buildScenes(): HeaderSceneArt[] {
  return [
    {
      id: 'eco-city' as const,
      name: 'Eco city',
      description:
        'A floating green city with planted towers, solar roofs, a pond, turning wind turbines and a waterfall.',
      raw: ecoScene(),
      css: ecoCss,
    },
    {
      id: 'mountain-village' as const,
      name: 'Mountain village',
      description:
        'A floating mountain village with snowy pines, A-frame cabins, chimney smoke, a stream and a campfire.',
      raw: alpScene(),
      css: alpCss,
    },
    {
      id: 'beach' as const,
      name: 'Beach',
      description:
        'A floating beach island with a waterfall hill, palms, a thatched hut, a jetty, a sailboat, a lantern, a villager, a crab and a gull.',
      raw: beachScene(),
      css: beachCss,
    },
    {
      id: 'sakura' as const,
      name: 'Sakura',
      description:
        'A floating cherry-blossom garden with a two-tier pagoda, a torii, a koi pond and bridge, a waterfall, a villager, a fox and stone lanterns.',
      raw: sakuraScene(),
      css: sakuraCss,
    },
  ].map(({ raw, ...scene }) => ({
    ...scene,
    viewBox: [0, 0, 1100, 240],
    layers: Object.fromEntries(
      Object.entries(raw.layers).map(([name, svg]) => [name, vectorTree(svg)]),
    ) as Record<SceneLayer, ReturnType<typeof vectorTree>>,
  }));
}
export function generatedFiles(): Map<string, string> {
  const files = new Map<string, string>();
  for (const scene of buildScenes()) {
    files.set(
      `${scene.id}.ts`,
      `${NOTICE}import type { HeaderSceneArt } from '../header-scene-art';\nconst scene: HeaderSceneArt = ${JSON.stringify(scene)};\nexport default scene;\n`,
    );
  }
  files.set(
    'styles.ts',
    `${NOTICE}export const headerSceneCss = ${JSON.stringify(sharedCss())};\n`,
  );
  return files;
}
/** Missing, changed and obsolete files all fail the check. No path-data assertions. */
export function staleOutputs(
  expected: ReadonlyMap<string, string>,
  actual: ReadonlyMap<string, string>,
): string[] {
  return [...new Set([...expected.keys(), ...actual.keys()])]
    .filter((path) => expected.get(path) !== actual.get(path))
    .sort();
}
